INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-debate-b2-01-01', 'lesson-debate-b2-01', 1, 'sentence', 'In my view, remote work is here to stay.', 'Na minha visão, o trabalho remoto veio para ficar.', '/ɪn maɪ vjuː rɪˈmoʊt wɜːrk ɪz hɪr tuː steɪ/', '"In my view" abre uma opinião pessoal com firmeza.', '[]'::jsonb, '[{"surface":"In","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"view","pos":"noun","ipa":"/vjuː/","gloss":"vista"},{"surface":"remote","pos":"adjective","ipa":"/rɪˈmoʊt/","gloss":"remoto"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"stay","pos":"verb","ipa":"/steɪ/","gloss":"ficar"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-01-02', 'lesson-debate-b2-01', 2, 'sentence', 'I strongly believe that education should be free.', 'Acredito firmemente que a educação deveria ser gratuita.', '/aɪ ˈstrɔːŋli bɪˈliːv ðæt ˌɛdʒuˈkeɪʃən ʃʊd biː friː/', '"Strongly believe" reforça a convicção.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"strongly","pos":"adverb","ipa":"/ˈstrɔːŋli/","gloss":"firmemente"},{"surface":"believe","pos":"verb","ipa":"/bɪˈliːv/","gloss":"acreditar"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"education","pos":"noun","ipa":"/ˌɛdʒuˈkeɪʃən/","gloss":"educação"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"free","pos":"adjective","ipa":"/friː/","gloss":"livre, disponível"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-01-03', 'lesson-debate-b2-01', 3, 'sentence', 'The reason I say this is that costs keep rising.', 'O motivo de eu dizer isso é que os custos não param de subir.', '/ðə ˈriːzən aɪ seɪ ðɪs ɪz ðæt kɔːsts kiːp ˈraɪzɪŋ/', '"The reason is that" liga a opinião à justificativa.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"reason","pos":"noun","ipa":"/ˈriːzən/","gloss":"motivo, razão"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"say","pos":"verb","ipa":"/seɪ/","gloss":"dizer"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"costs","pos":"verb","ipa":"/kɔːsts/","gloss":"custa"},{"surface":"keep","pos":"verb","ipa":"/kiːp/","gloss":"manter"},{"surface":"rising","pos":"verb","ipa":"/ˈraɪzɪŋ/","gloss":"subindo"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-01-04', 'lesson-debate-b2-01', 4, 'sentence', 'It seems to me that we are asking the wrong question.', 'Parece-me que estamos fazendo a pergunta errada.', '/ɪt siːmz tuː miː ðæt wiː ɑːr ˈæskɪŋ ðə rɔːŋ ˈkwɛstʃən/', '"It seems to me" é uma opinião mais cuidadosa.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"seems","pos":"verb","ipa":"/siːmz/","gloss":"parece"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"asking","pos":"verb","ipa":"/ˈæskɪŋ/","gloss":"pedindo, perguntando"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"wrong","pos":"adjective","ipa":"/rɔːŋ/","gloss":"errado"},{"surface":"question","pos":"noun","ipa":"/ˈkwɛstʃən/","gloss":"pergunta"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-01-05', 'lesson-debate-b2-01', 5, 'sentence', 'As far as I am concerned, safety comes first.', 'Quanto a mim, a segurança vem em primeiro lugar.', '/æz fɑːr æz aɪ æm kənˈsɜːrnd ˈseɪfti kʌmz fɜːrst/', '"As far as I am concerned" = no que me diz respeito.', '[]'::jsonb, '[{"surface":"As","pos":"conjunction","ipa":"/æz/","gloss":"como"},{"surface":"far","pos":"adjective","ipa":"/fɑːr/","gloss":"longe"},{"surface":"as","pos":"conjunction","ipa":"/æz/","gloss":"como"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"am","pos":"auxiliary verb","ipa":"/æm/","gloss":"sou, estou"},{"surface":"concerned","pos":"adjective","ipa":"/kənˈsɜːrnd/","gloss":"preocupado, envolvido"},{"surface":"safety","pos":"noun","ipa":"/ˈseɪfti/","gloss":"segurança"},{"surface":"comes","pos":"verb","ipa":"/kʌmz/","gloss":"vem (he/she/it)"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-01-06', 'lesson-debate-b2-01', 6, 'sentence', 'I would argue that this is a matter of fairness.', 'Eu diria que isso é uma questão de justiça.', '/aɪ wʊd ˈɑːrɡjuː ðæt ðɪs ɪz ə ˈmætər ʌv ˈfɛrnəs/', '"I would argue that" apresenta uma tese de forma educada.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"argue","pos":"verb","ipa":"/ˈɑːrɡjuː/","gloss":"defender, sustentar"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"matter","pos":"noun","ipa":"/ˈmætər/","gloss":"questão, assunto"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"fairness","pos":"noun","ipa":"/ˈfɛrnəs/","gloss":"justiça, equidade"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-01-07', 'lesson-debate-b2-01', 7, 'sentence', 'Personally, I think the benefits outweigh the risks.', 'Pessoalmente, acho que os benefícios superam os riscos.', '/ˈpɜːrsənəli aɪ θɪŋk ðə ˈbɛnəfɪts ˌaʊtˈweɪ ðə rɪsks/', '"Outweigh" = pesar mais que.', '[]'::jsonb, '[{"surface":"Personally","pos":"adverb","ipa":"/ˈpɜːrsənəli/","gloss":"pessoalmente"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"think","pos":"verb","ipa":"/θɪŋk/","gloss":"achar, pensar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"benefits","pos":"noun","ipa":"/ˈbɛnəfɪts/","gloss":"benefícios"},{"surface":"outweigh","pos":"verb","ipa":"/ˌaʊtˈweɪ/","gloss":"pesar mais que"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"risks","pos":"noun","ipa":"/rɪsks/","gloss":"riscos"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-01-08', 'lesson-debate-b2-01', 8, 'sentence', 'That is exactly why we need a clear policy.', 'É exatamente por isso que precisamos de uma política clara.', '/ðæt ɪz ɪɡˈzæktli waɪ wiː niːd ə klɪr ˈpɑːləsi/', '"That is why" conclui o raciocínio.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"exactly","pos":"adverb","ipa":"/ɪɡˈzæktli/","gloss":"exatamente"},{"surface":"why","pos":"adverb","ipa":"/waɪ/","gloss":"por que"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"clear","pos":"adjective","ipa":"/klɪr/","gloss":"claro"},{"surface":"policy","pos":"noun","ipa":"/ˈpɑːləsi/","gloss":"política, regra"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-01-09', 'lesson-debate-b2-01', 9, 'sentence', 'To put it simply, the plan is too expensive.', 'Resumindo, o plano é caro demais.', '/tuː pʊt ɪt ˈsɪmpli ðə plæn ɪz tuː ɪkˈspɛnsɪv/', '"To put it simply" simplifica antes da conclusão.', '[]'::jsonb, '[{"surface":"To","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"simply","pos":"adverb","ipa":"/ˈsɪmpli/","gloss":"com simplicidade"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"plan","pos":"noun","ipa":"/plæn/","gloss":"plano"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"too","pos":"adverb","ipa":"/tuː/","gloss":"demais"},{"surface":"expensive","pos":"adjective","ipa":"/ɪkˈspɛnsɪv/","gloss":"caro"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-01-10', 'lesson-debate-b2-01', 10, 'sentence', 'I feel very strongly about this issue.', 'Tenho uma posição muito firme sobre esse assunto.', '/aɪ fiːl ˈvɛri ˈstrɔːŋli əˈbaʊt ðɪs ˈɪʃuː/', '"Feel strongly about" = ter opinião forte.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"feel","pos":"verb","ipa":"/fiːl/","gloss":"sentir"},{"surface":"very","pos":"adverb","ipa":"/ˈvɛri/","gloss":"muito"},{"surface":"strongly","pos":"adverb","ipa":"/ˈstrɔːŋli/","gloss":"firmemente"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"issue","pos":"noun","ipa":"/ˈɪʃuː/","gloss":"assunto, problema"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-debate-b2-02-01', 'lesson-debate-b2-02', 1, 'sentence', 'For instance, several cities have already done this.', 'Por exemplo, várias cidades já fizeram isso.', '/fɔːr ˈɪnstəns ˈsɛvrəl ˈsɪtiz hæv ɔːlˈrɛdi dʌn ðɪs/', '"For instance" introduz um exemplo.', '[]'::jsonb, '[{"surface":"For","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"instance","pos":"noun","ipa":"/ˈɪnstəns/","gloss":"exemplo, caso"},{"surface":"several","pos":"determiner","ipa":"/ˈsɛvrəl/","gloss":"vários"},{"surface":"cities","pos":"noun","ipa":"/ˈsɪtiz/","gloss":"cidades"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"already","pos":"adverb","ipa":"/ɔːlˈrɛdi/","gloss":"já"},{"surface":"done","pos":"adjective","ipa":"/dʌn/","gloss":"pronto, feito"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-02-02', 'lesson-debate-b2-02', 2, 'sentence', 'Studies show that sleep affects memory.', 'Estudos mostram que o sono afeta a memória.', '/ˈstʌdiz ʃoʊ ðæt sliːp əˈfɛkts ˈmɛməri/', '"Studies show" cita pesquisa sem apontar uma.', '[]'::jsonb, '[{"surface":"Studies","pos":"verb","ipa":"/ˈstʌdiz/","gloss":"estuda"},{"surface":"show","pos":"verb","ipa":"/ʃoʊ/","gloss":"aparecer (show up)"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"sleep","pos":"verb","ipa":"/sliːp/","gloss":"dormir"},{"surface":"affects","pos":"verb","ipa":"/əˈfɛkts/","gloss":"afeta"},{"surface":"memory","pos":"noun","ipa":"/ˈmɛməri/","gloss":"memória"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-02-03', 'lesson-debate-b2-02', 3, 'sentence', 'According to the latest report, crime is down.', 'De acordo com o relatório mais recente, o crime diminuiu.', '/əˈkɔːrdɪŋ tuː ðə ˈleɪtɪst rɪˈpɔːrt kraɪm ɪz daʊn/', '"According to" atribui a fonte.', '[]'::jsonb, '[{"surface":"According","pos":"adverb","ipa":"/əˈkɔːrdɪŋ/","gloss":"de acordo (com)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"latest","pos":"adjective","ipa":"/ˈleɪtɪst/","gloss":"mais recente"},{"surface":"report","pos":"verb","ipa":"/rɪˈpɔːrt/","gloss":"registrar, relatar"},{"surface":"crime","pos":"noun","ipa":"/kraɪm/","gloss":"crime"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-02-04', 'lesson-debate-b2-02', 4, 'sentence', 'This is backed up by solid evidence.', 'Isso é sustentado por evidências sólidas.', '/ðɪs ɪz bækt ʌp baɪ ˈsɑːlɪd ˈɛvɪdəns/', '"Backed up by" = apoiado em.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"backed","pos":"verb","ipa":"/bækt/","gloss":"apoiado"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"solid","pos":"adjective","ipa":"/ˈsɑːlɪd/","gloss":"sólido"},{"surface":"evidence","pos":"noun","ipa":"/ˈɛvɪdəns/","gloss":"evidência"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-02-05', 'lesson-debate-b2-02', 5, 'sentence', 'A good example of this is the new law.', 'Um bom exemplo disso é a nova lei.', '/ə ɡʊd ɪɡˈzæmpəl ʌv ðɪs ɪz ðə nuː lɔː/', 'Pede ao ouvinte que examine um caso.', '[]'::jsonb, '[{"surface":"A","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"good","pos":"adjective","ipa":"/ɡʊd/","gloss":"bom"},{"surface":"example","pos":"noun","ipa":"/ɪɡˈzæmpəl/","gloss":"exemplo"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"law","pos":"noun","ipa":"/lɔː/","gloss":"lei"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-02-06', 'lesson-debate-b2-02', 6, 'sentence', 'Let us look at the numbers more closely.', 'Vamos olhar os números mais de perto.', '/lɛt ʌs lʊk æt ðə ˈnʌmbərz mɔːr ˈkloʊsli/', 'Convida a analisar os dados.', '[]'::jsonb, '[{"surface":"Let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"look","pos":"noun","ipa":"/lʊk/","gloss":"olhada"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"numbers","pos":"noun","ipa":"/ˈnʌmbərz/","gloss":"números"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"closely","pos":"adverb","ipa":"/ˈkloʊsli/","gloss":"de perto"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-02-07', 'lesson-debate-b2-02', 7, 'sentence', 'That claim is not supported by the data.', 'Essa afirmação não é sustentada pelos dados.', '/ðæt kleɪm ɪz nɑːt səˈpɔːrtɪd baɪ ðə ˈdeɪtə/', '"Not supported by" = sem base nos dados.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"claim","pos":"noun","ipa":"/kleɪm/","gloss":"retirada; reclamação"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"supported","pos":"verb","ipa":"/səˈpɔːrtɪd/","gloss":"sustentado, apoiado"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"data","pos":"noun","ipa":"/ˈdeɪtə/","gloss":"dados"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-02-08', 'lesson-debate-b2-02', 8, 'sentence', 'In fact, the opposite is true.', 'Na verdade, o contrário é verdade.', '/ɪn fækt ðə ˈɑːpəzɪt ɪz truː/', '"In fact" corrige com firmeza.', '[]'::jsonb, '[{"surface":"In","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"fact","pos":"noun","ipa":"/fækt/","gloss":"fato"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"opposite","pos":"preposition","ipa":"/ˈɑːpəzɪt/","gloss":"em frente a, do outro lado"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"true","pos":"adjective","ipa":"/truː/","gloss":"verdadeiro"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-02-09', 'lesson-debate-b2-02', 9, 'sentence', 'Take, for example, the case of Japan.', 'Tome, por exemplo, o caso do Japão.', '/teɪk fɔːr ɪɡˈzæmpəl ðə keɪs ʌv dʒəˈpæn/', '"Take, for example" é um jeito retórico de exemplificar.', '[]'::jsonb, '[{"surface":"Take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"example","pos":"noun","ipa":"/ɪɡˈzæmpəl/","gloss":"exemplo"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"case","pos":"noun","ipa":"/keɪs/","gloss":"capa, caso"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"Japan","pos":"proper noun","ipa":"/dʒəˈpæn/","gloss":"Japão"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-02-10', 'lesson-debate-b2-02', 10, 'sentence', 'There is plenty of proof that it works.', 'Há muita prova de que funciona.', '/ðɛr ɪz ˈplɛnti ʌv pruːf ðæt ɪt wɜːrks/', '"Plenty of" = bastante; "proof" não tem plural.', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"plenty","pos":"noun","ipa":"/ˈplɛnti/","gloss":"bastante, muito"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"proof","pos":"noun","ipa":"/pruːf/","gloss":"prova"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"works","pos":"verb","ipa":"/wɜːrks/","gloss":"funciona, serve"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-debate-b2-03-01', 'lesson-debate-b2-03', 1, 'sentence', 'I take your point, but I see it differently.', 'Entendo o que você diz, mas vejo de outro jeito.', '/aɪ teɪk jʊr pɔɪnt bʌt aɪ siː ɪt ˈdɪfrəntli/', '"I take your point" reconhece o argumento antes de rebater.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"point","pos":"noun","ipa":"/pɔɪnt/","gloss":"ponto, argumento"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"see","pos":"verb","ipa":"/siː/","gloss":"ver, entender"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"differently","pos":"adverb","ipa":"/ˈdɪfrəntli/","gloss":"de outro jeito"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-03-02', 'lesson-debate-b2-03', 2, 'sentence', 'That might be true, but it overlooks one thing.', 'Pode ser verdade, mas isso ignora um ponto.', '/ðæt maɪt biː truː bʌt ɪt ˌoʊvərˈlʊks wʌn θɪŋ/', '"Overlook" = deixar passar, não considerar.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"true","pos":"adjective","ipa":"/truː/","gloss":"verdadeiro"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"overlooks","pos":"verb","ipa":"/ˌoʊvərˈlʊks/","gloss":"ignora, deixa passar"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"thing","pos":"noun","ipa":"/θɪŋ/","gloss":"coisa"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-03-03', 'lesson-debate-b2-03', 3, 'sentence', 'I am not convinced that this will solve the problem.', 'Não estou convencido de que isso resolva o problema.', '/aɪ æm nɑːt kənˈvɪnst ðæt ðɪs wɪl sɑːlv ðə ˈprɑːbləm/', 'Cético, mas não hostil.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"am","pos":"auxiliary verb","ipa":"/æm/","gloss":"sou, estou"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"convinced","pos":"adjective","ipa":"/kənˈvɪnst/","gloss":"convencido"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"solve","pos":"verb","ipa":"/sɑːlv/","gloss":"resolver"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-03-04', 'lesson-debate-b2-03', 4, 'sentence', 'On the contrary, it could make things worse.', 'Pelo contrário, pode piorar as coisas.', '/ɑːn ðə ˈkɑːntrɛri ɪt kʊd meɪk θɪŋz wɜːrs/', '"On the contrary" nega a ideia anterior.', '[]'::jsonb, '[{"surface":"On","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"contrary","pos":"noun","ipa":"/ˈkɑːntrɛri/","gloss":"contrário"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"things","pos":"noun","ipa":"/θɪŋz/","gloss":"coisas"},{"surface":"worse","pos":"adjective","ipa":"/wɜːrs/","gloss":"pior"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-03-05', 'lesson-debate-b2-03', 5, 'sentence', 'The problem with that argument is that it ignores costs.', 'O problema desse argumento é que ele ignora os custos.', '/ðə ˈprɑːbləm wɪð ðæt ˈɑːrɡjəmənt ɪz ðæt ɪt ɪɡˈnɔːrz kɔːsts/', 'Aponta a falha sem atacar a pessoa.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"argument","pos":"noun","ipa":"/ˈɑːrɡjəmənt/","gloss":"argumento"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"ignores","pos":"verb","ipa":"/ɪɡˈnɔːrz/","gloss":"ignora"},{"surface":"costs","pos":"verb","ipa":"/kɔːsts/","gloss":"custa"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-03-06', 'lesson-debate-b2-03', 6, 'sentence', 'That is an oversimplification.', 'Isso é uma simplificação exagerada.', '/ðæt ɪz ən ˌoʊvərˌsɪmpləfɪˈkeɪʃən/', '"Oversimplification" = simplificar demais.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"oversimplification","pos":"noun","ipa":"/ˌoʊvərˌsɪmpləfɪˈkeɪʃən/","gloss":"simplificação exagerada"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-03-07', 'lesson-debate-b2-03', 7, 'sentence', 'You are assuming that everyone agrees.', 'Você está presumindo que todos concordam.', '/juː ɑːr əˈsuːmɪŋ ðæt ˈɛvriwʌn əˈɡriːz/', 'Expõe uma premissa não provada.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"assuming","pos":"verb","ipa":"/əˈsuːmɪŋ/","gloss":"presumindo"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"everyone","pos":"pronoun","ipa":"/ˈɛvriwʌn/","gloss":"todo mundo, pessoal"},{"surface":"agrees","pos":"verb","ipa":"/əˈɡriːz/","gloss":"concorda"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-03-08', 'lesson-debate-b2-03', 8, 'sentence', 'I would question that conclusion.', 'Eu questionaria essa conclusão.', '/aɪ wʊd ˈkwɛstʃən ðæt kənˈkluːʒən/', '"Question" como verbo = pôr em dúvida.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"question","pos":"noun","ipa":"/ˈkwɛstʃən/","gloss":"pergunta"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"conclusion","pos":"noun","ipa":"/kənˈkluːʒən/","gloss":"conclusão"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-03-09', 'lesson-debate-b2-03', 9, 'sentence', 'That does not necessarily follow.', 'Isso não decorre necessariamente.', '/ðæt dʌz nɑːt ˌnɛsəˈsɛrəli ˈfɑːloʊ/', 'Forma lógica de dizer "nem sempre é assim".', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"necessarily","pos":"adverb","ipa":"/ˌnɛsəˈsɛrəli/","gloss":"necessariamente"},{"surface":"follow","pos":"verb","ipa":"/ˈfɑːloʊ/","gloss":"seguir"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-03-10', 'lesson-debate-b2-03', 10, 'sentence', 'By the same logic, we would have to ban cars.', 'Pela mesma lógica, teríamos que proibir os carros.', '/baɪ ðə seɪm ˈlɑːdʒɪk wiː wʊd hæv tuː bæn kɑːrz/', 'Reductio: leva o argumento ao extremo.', '[]'::jsonb, '[{"surface":"By","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"same","pos":"adjective","ipa":"/seɪm/","gloss":"mesmo"},{"surface":"logic","pos":"noun","ipa":"/ˈlɑːdʒɪk/","gloss":"lógica"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"ban","pos":"verb","ipa":"/bæn/","gloss":"proibir"},{"surface":"cars","pos":"noun","ipa":"/kɑːrz/","gloss":"carros"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-debate-b2-04-01', 'lesson-debate-b2-04', 1, 'sentence', 'I will grant you that the cost is high.', 'Concordo que o custo é alto.', '/aɪ wɪl ɡrænt juː ðæt ðə kɔːst ɪz haɪ/', '"Grant" = admitir um ponto.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"grant","pos":"verb","ipa":"/ɡrænt/","gloss":"admitir, conceder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"cost","pos":"verb","ipa":"/kɔːst/","gloss":"custar"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"high","pos":"adjective","ipa":"/haɪ/","gloss":"alto"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-04-02', 'lesson-debate-b2-04', 2, 'sentence', 'You are right about that, but there is more to it.', 'Você tem razão nisso, mas há mais coisa.', '/juː ɑːr raɪt əˈbaʊt ðæt bʌt ðɛr ɪz mɔːr tuː ɪt/', 'Concede e amplia a discussão.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"right","pos":"adverb","ipa":"/raɪt/","gloss":"bem; né? (right?)"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-04-03', 'lesson-debate-b2-04', 3, 'sentence', 'Admittedly, the plan has some flaws.', 'É verdade que o plano tem algumas falhas.', '/ədˈmɪtɪdli ðə plæn hæz sʌm flɔːz/', '"Admittedly" = é preciso admitir.', '[]'::jsonb, '[{"surface":"Admittedly","pos":"adverb","ipa":"/ədˈmɪtɪdli/","gloss":"é preciso admitir"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"plan","pos":"noun","ipa":"/plæn/","gloss":"plano"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"flaws","pos":"noun","ipa":"/flɔːz/","gloss":"falhas"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-04-04', 'lesson-debate-b2-04', 4, 'sentence', 'Even so, the benefits are hard to ignore.', 'Mesmo assim, os benefícios são difíceis de ignorar.', '/ˈiːvən soʊ ðə ˈbɛnəfɪts ɑːr hɑːrd tuː ɪɡˈnɔːr/', '"Even so" retoma o ponto principal.', '[]'::jsonb, '[{"surface":"Even","pos":"adverb","ipa":"/ˈiːvən/","gloss":"até, mesmo"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"benefits","pos":"noun","ipa":"/ˈbɛnəfɪts/","gloss":"benefícios"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"hard","pos":"adjective","ipa":"/hɑːrd/","gloss":"duro, difícil"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"ignore","pos":"verb","ipa":"/ɪɡˈnɔːr/","gloss":"ignorar"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-04-05', 'lesson-debate-b2-04', 5, 'sentence', 'That said, we should not give up yet.', 'Dito isso, não devemos desistir ainda.', '/ðæt sɛd wiː ʃʊd nɑːt ɡɪv ʌp jɛt/', '"That said" faz a virada depois da concessão.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"said","pos":"verb","ipa":"/sɛd/","gloss":"disse, dito"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"give","pos":"verb","ipa":"/ɡɪv/","gloss":"dar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"yet","pos":"adverb","ipa":"/jɛt/","gloss":"ainda"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-04-06', 'lesson-debate-b2-04', 6, 'sentence', 'Fair enough, but let me explain why I disagree.', 'Justo, mas deixa eu explicar por que discordo.', '/fɛr ɪˈnʌf bʌt lɛt miː ɪkˈspleɪn waɪ aɪ ˌdɪsəˈɡriː/', 'Concede e pede espaço para falar.', '[]'::jsonb, '[{"surface":"Fair","pos":"adjective","ipa":"/fɛr/","gloss":"justo"},{"surface":"enough","pos":"adverb","ipa":"/ɪˈnʌf/","gloss":"o bastante"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"explain","pos":"verb","ipa":"/ɪkˈspleɪn/","gloss":"explicar"},{"surface":"why","pos":"adverb","ipa":"/waɪ/","gloss":"por que"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"disagree","pos":"verb","ipa":"/ˌdɪsəˈɡriː/","gloss":"discordar"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-04-07', 'lesson-debate-b2-04', 7, 'sentence', 'I accept that there are risks involved.', 'Aceito que há riscos envolvidos.', '/aɪ əkˈsɛpt ðæt ðɛr ɑːr rɪsks ɪnˈvɑːlvd/', 'Admite sem abandonar a tese.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"accept","pos":"verb","ipa":"/əkˈsɛpt/","gloss":"aceitar"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"risks","pos":"noun","ipa":"/rɪsks/","gloss":"riscos"},{"surface":"involved","pos":"adjective","ipa":"/ɪnˈvɑːlvd/","gloss":"envolvido"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-04-08', 'lesson-debate-b2-04', 8, 'sentence', 'While that is true, it is only half the story.', 'Embora seja verdade, é só metade da história.', '/waɪl ðæt ɪz truː ɪt ɪz ˈoʊnli hæf ðə ˈstɔːri/', '"While" com sentido de "embora".', '[]'::jsonb, '[{"surface":"While","pos":"noun","ipa":"/waɪl/","gloss":"tempo (a while = um tempo)"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"true","pos":"adjective","ipa":"/truː/","gloss":"verdadeiro"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"only","pos":"adverb","ipa":"/ˈoʊnli/","gloss":"só, apenas"},{"surface":"half","pos":"noun","ipa":"/hæf/","gloss":"metade, meio"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"story","pos":"noun","ipa":"/ˈstɔːri/","gloss":"história"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-04-09', 'lesson-debate-b2-04', 9, 'sentence', 'Let us set that aside and focus on the main issue.', 'Vamos deixar isso de lado e focar no assunto principal.', '/lɛt ʌs sɛt ðæt əˈsaɪd ænd ˈfoʊkəs ɑːn ðə meɪn ˈɪʃuː/', '"Set aside" = deixar de lado.', '[]'::jsonb, '[{"surface":"Let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"set","pos":"verb","ipa":"/sɛt/","gloss":"definir"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"aside","pos":"adverb","ipa":"/əˈsaɪd/","gloss":"de lado"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"focus","pos":"verb","ipa":"/ˈfoʊkəs/","gloss":"focar"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"main","pos":"adjective","ipa":"/meɪn/","gloss":"principal"},{"surface":"issue","pos":"noun","ipa":"/ˈɪʃuː/","gloss":"assunto, problema"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-04-10', 'lesson-debate-b2-04', 10, 'sentence', 'The real question is who pays for it.', 'A verdadeira questão é quem paga por isso.', '/ðə ˈriːəl ˈkwɛstʃən ɪz huː peɪz fɔːr ɪt/', 'Redireciona o debate para o ponto que importa.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"real","pos":"adjective","ipa":"/ˈriːəl/","gloss":"real"},{"surface":"question","pos":"noun","ipa":"/ˈkwɛstʃən/","gloss":"pergunta"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"pays","pos":"verb","ipa":"/peɪz/","gloss":"paga"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-debate-b2-05-01', 'lesson-debate-b2-05', 1, 'sentence', 'What exactly do you mean by that?', 'O que exatamente você quer dizer com isso?', '/wʌt ɪɡˈzæktli duː juː miːn baɪ ðæt/', '"What exactly" pede precisão.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"exactly","pos":"adverb","ipa":"/ɪɡˈzæktli/","gloss":"exatamente"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"mean","pos":"verb","ipa":"/miːn/","gloss":"significar, querer dizer"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-05-02', 'lesson-debate-b2-05', 2, 'sentence', 'Could you give me a concrete example?', 'Você poderia me dar um exemplo concreto?', '/kʊd juː ɡɪv miː ə ˈkɑːnkriːt ɪɡˈzæmpəl/', '"Concrete" = específico, real.', '[]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"give","pos":"verb","ipa":"/ɡɪv/","gloss":"dar"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"concrete","pos":"adjective","ipa":"/ˈkɑːnkriːt/","gloss":"concreto"},{"surface":"example","pos":"noun","ipa":"/ɪɡˈzæmpəl/","gloss":"exemplo"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-05-03', 'lesson-debate-b2-05', 3, 'sentence', 'How do you know that is the case?', 'Como você sabe que é assim?', '/haʊ duː juː noʊ ðæt ɪz ðə keɪs/', 'Pede a base da afirmação.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"know","pos":"verb","ipa":"/noʊ/","gloss":"saber"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"case","pos":"noun","ipa":"/keɪs/","gloss":"capa, caso"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-05-04', 'lesson-debate-b2-05', 4, 'sentence', 'Who would benefit from this change?', 'Quem se beneficiaria dessa mudança?', '/huː wʊd ˈbɛnɪfɪt frʌm ðɪs tʃeɪndʒ/', 'Pergunta de interesse e justiça.', '[]'::jsonb, '[{"surface":"Who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"benefit","pos":"verb","ipa":"/ˈbɛnɪfɪt/","gloss":"beneficiar-se"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-05-05', 'lesson-debate-b2-05', 5, 'sentence', 'What happens if the plan fails?', 'O que acontece se o plano falhar?', '/wʌt ˈhæpənz ɪf ðə plæn feɪlz/', 'Testa o risco da proposta.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"happens","pos":"verb","ipa":"/ˈhæpənz/","gloss":"acontece"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"plan","pos":"noun","ipa":"/plæn/","gloss":"plano"},{"surface":"fails","pos":"verb","ipa":"/feɪlz/","gloss":"falha"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-05-06', 'lesson-debate-b2-05', 6, 'sentence', 'Is that really the only option?', 'Será que essa é mesmo a única opção?', '/ɪz ðæt ˈriːəli ðə ˈoʊnli ˈɑːpʃən/', '"Really" faz a pergunta soar cética.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"really","pos":"adverb","ipa":"/ˈriːəli/","gloss":"muito, de verdade"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"only","pos":"adverb","ipa":"/ˈoʊnli/","gloss":"só, apenas"},{"surface":"option","pos":"noun","ipa":"/ˈɑːpʃən/","gloss":"opção"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-05-07', 'lesson-debate-b2-05', 7, 'sentence', 'Are you saying that we should do nothing?', 'Você está dizendo que não devemos fazer nada?', '/ɑːr juː ˈseɪɪŋ ðæt wiː ʃʊd duː ˈnʌθɪŋ/', 'Exagera para o outro esclarecer.', '[]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"saying","pos":"verb","ipa":"/ˈseɪɪŋ/","gloss":"dizendo"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"nothing","pos":"pronoun","ipa":"/ˈnʌθɪŋ/","gloss":"nada"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-05-08', 'lesson-debate-b2-05', 8, 'sentence', 'Where is the evidence for that claim?', 'Onde está a evidência dessa afirmação?', '/wɛr ɪz ðə ˈɛvɪdəns fɔːr ðæt kleɪm/', 'Direta; usar com cuidado, pois pode soar ríspida.', '[]'::jsonb, '[{"surface":"Where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"evidence","pos":"noun","ipa":"/ˈɛvɪdəns/","gloss":"evidência"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"claim","pos":"noun","ipa":"/kleɪm/","gloss":"retirada; reclamação"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-05-09', 'lesson-debate-b2-05', 9, 'sentence', 'Have you considered the long-term effects?', 'Você considerou os efeitos de longo prazo?', '/hæv juː kənˈsɪdərd ðə ˌlɔːŋ ˈtɜːrm ɪˈfɛkts/', 'Pergunta educada que mostra uma lacuna.', '[]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"considered","pos":"verb","ipa":"/kənˈsɪdərd/","gloss":"considerou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"long-term","pos":"adjective","ipa":"/ˌlɔːŋ ˈtɜːrm/","gloss":"de longo prazo"},{"surface":"effects","pos":"noun","ipa":"/ɪˈfɛkts/","gloss":"efeitos"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-05-10', 'lesson-debate-b2-05', 10, 'sentence', 'Would you say that again, more slowly?', 'Você poderia repetir, mais devagar?', '/wʊd juː seɪ ðæt əˈɡɛn mɔːr ˈsloʊli/', 'Também vale em debate quando o ritmo é rápido.', '[]'::jsonb, '[{"surface":"Would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"say","pos":"verb","ipa":"/seɪ/","gloss":"dizer"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"again","pos":"adverb","ipa":"/əˈɡɛn/","gloss":"de novo"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"slowly","pos":"adverb","ipa":"/ˈsloʊli/","gloss":"devagar"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-debate-b2-06-01', 'lesson-debate-b2-06', 1, 'sentence', 'In conclusion, the evidence points one way.', 'Em conclusão, as evidências apontam para um lado.', '/ɪn kənˈkluːʒən ðə ˈɛvɪdəns pɔɪnts wʌn weɪ/', '"In conclusion" sinaliza o fim.', '[]'::jsonb, '[{"surface":"In","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"conclusion","pos":"noun","ipa":"/kənˈkluːʒən/","gloss":"conclusão"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"evidence","pos":"noun","ipa":"/ˈɛvɪdəns/","gloss":"evidência"},{"surface":"points","pos":"noun","ipa":"/pɔɪnts/","gloss":"pontos"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"way","pos":"noun","ipa":"/weɪ/","gloss":"caminho; jeito"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-06-02', 'lesson-debate-b2-06', 2, 'sentence', 'All things considered, I believe we should proceed.', 'Considerando tudo, acredito que devemos seguir em frente.', '/ɔːl θɪŋz kənˈsɪdərd aɪ bɪˈliːv wiː ʃʊd prəˈsiːd/', '"All things considered" resume o equilíbrio.', '[]'::jsonb, '[{"surface":"All","pos":"determiner","ipa":"/ɔːl/","gloss":"tudo, todos"},{"surface":"things","pos":"noun","ipa":"/θɪŋz/","gloss":"coisas"},{"surface":"considered","pos":"verb","ipa":"/kənˈsɪdərd/","gloss":"considerou"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"believe","pos":"verb","ipa":"/bɪˈliːv/","gloss":"acreditar"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"proceed","pos":"verb","ipa":"/prəˈsiːd/","gloss":"prosseguir"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-06-03', 'lesson-debate-b2-06', 3, 'sentence', 'The bottom line is that we cannot afford to wait.', 'O ponto central é que não podemos nos dar ao luxo de esperar.', '/ðə ˈbɑːtəm laɪn ɪz ðæt wiː ˈkænɑːt əˈfɔːrd tuː weɪt/', '"The bottom line" = o essencial.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bottom","pos":"noun","ipa":"/ˈbɑːtəm/","gloss":"fundo"},{"surface":"line","pos":"noun","ipa":"/laɪn/","gloss":"linha"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"cannot","pos":"verb","ipa":"/ˈkænɑːt/","gloss":"não posso, não consigo"},{"surface":"afford","pos":"verb","ipa":"/əˈfɔːrd/","gloss":"ter condição de pagar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"wait","pos":"noun","ipa":"/weɪt/","gloss":"espera; esperar"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-06-04', 'lesson-debate-b2-06', 4, 'sentence', 'I urge you to think about the consequences.', 'Peço que você pense nas consequências.', '/aɪ ɜːrdʒ juː tuː θɪŋk əˈbaʊt ðə ˈkɑːnsəkwɛnsɪz/', '"Urge" = pedir com insistência.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"urge","pos":"verb","ipa":"/ɜːrdʒ/","gloss":"pedir com insistência"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"think","pos":"verb","ipa":"/θɪŋk/","gloss":"achar, pensar"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"consequences","pos":"noun","ipa":"/ˈkɑːnsəkwɛnsɪz/","gloss":"consequências"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-06-05', 'lesson-debate-b2-06', 5, 'sentence', 'We have a chance to get this right.', 'Temos a chance de acertar nisso.', '/wiː hæv ə tʃæns tuː ɡɛt ðɪs raɪt/', 'Apelo positivo para a ação.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"chance","pos":"noun","ipa":"/tʃæns/","gloss":"chance, oportunidade"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"right","pos":"adverb","ipa":"/raɪt/","gloss":"bem; né? (right?)"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-06-06', 'lesson-debate-b2-06', 6, 'sentence', 'Imagine what we could achieve together.', 'Imagine o que poderíamos conquistar juntos.', '/ɪˈmædʒɪn wʌt wiː kʊd əˈtʃiːv təˈɡɛðər/', 'Convida o ouvinte a visualizar.', '[]'::jsonb, '[{"surface":"Imagine","pos":"verb","ipa":"/ɪˈmædʒɪn/","gloss":"imaginar"},{"surface":"what","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"achieve","pos":"verb","ipa":"/əˈtʃiːv/","gloss":"conquistar, alcançar"},{"surface":"together","pos":"adverb","ipa":"/təˈɡɛðər/","gloss":"juntos"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-06-07', 'lesson-debate-b2-06', 7, 'sentence', 'The choice is clear, and the time is now.', 'A escolha é clara, e o momento é agora.', '/ðə tʃɔɪs ɪz klɪr ænd ðə taɪm ɪz naʊ/', 'Fecho retórico com ritmo.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"choice","pos":"noun","ipa":"/tʃɔɪs/","gloss":"escolha"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"clear","pos":"adjective","ipa":"/klɪr/","gloss":"claro"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-06-08', 'lesson-debate-b2-06', 8, 'sentence', 'Let me leave you with one final thought.', 'Deixa eu te deixar com um último pensamento.', '/lɛt miː liːv juː wɪð wʌn ˈfaɪnəl θɔːt/', 'Abre o fechamento.', '[]'::jsonb, '[{"surface":"Let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"final","pos":"adjective","ipa":"/ˈfaɪnəl/","gloss":"final, último"},{"surface":"thought","pos":"verb","ipa":"/θɔːt/","gloss":"pensou, pensado"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-06-09', 'lesson-debate-b2-06', 9, 'sentence', 'I hope I have made my position clear.', 'Espero ter deixado minha posição clara.', '/aɪ hoʊp aɪ hæv meɪd maɪ pəˈzɪʃən klɪr/', 'Encerra com cortesia.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"hope","pos":"verb","ipa":"/hoʊp/","gloss":"esperar (ter esperança)"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"made","pos":"verb","ipa":"/meɪd/","gloss":"fez, feito"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"position","pos":"noun","ipa":"/pəˈzɪʃən/","gloss":"cargo, vaga"},{"surface":"clear","pos":"adjective","ipa":"/klɪr/","gloss":"claro"}]'::jsonb, NULL, NULL),
  ('unit-debate-b2-06-10', 'lesson-debate-b2-06', 10, 'sentence', 'Thank you for listening, and I welcome your questions.', 'Obrigado por ouvir, e recebo suas perguntas.', '/θæŋk juː fɔːr ˈlɪsənɪŋ ænd aɪ ˈwɛlkəm jʊr ˈkwɛstʃənz/', 'Encerramento formal de apresentação ou debate.', '[]'::jsonb, '[{"surface":"Thank","pos":"verb","ipa":"/θæŋk/","gloss":"agradecer"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"listening","pos":"verb","ipa":"/ˈlɪsənɪŋ/","gloss":"ouvindo"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"welcome","pos":"adjective","ipa":"/ˈwɛlkəm/","gloss":"bem-vindo"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"questions","pos":"noun","ipa":"/ˈkwɛstʃənz/","gloss":"perguntas, dúvidas"}]'::jsonb, NULL, NULL)
